-- INV-POS Postgres schema (cloud mode), equivalent to SQLite schema v5.
-- Applied automatically by app/db.py:init_db() on an empty database. Do not edit an applied
-- database by hand: add a numbered migration in app/pg.py instead.
--
-- Differences from SQLite, all deliberate:
--   * COLLATE NOCASE names are CITEXT (case-insensitive, needs the citext extension).
--   * Dates/times stay TEXT 'YYYY-MM-DD HH:MM:SS' in local time, exactly like SQLite, so every
--     query and report works unchanged. The session time zone is set from TZ (Africa/Nairobi).
--   * round(double precision, int) is added: SQLite's ROUND(x, 2) works on REAL, Postgres's only on NUMERIC.

CREATE EXTENSION IF NOT EXISTS citext;

CREATE OR REPLACE FUNCTION round(double precision, integer) RETURNS double precision
    LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT round($1::numeric, $2)::double precision $$;

CREATE TABLE schema_meta (id INTEGER PRIMARY KEY CHECK (id = 1), version INTEGER NOT NULL);

CREATE TABLE staff (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, pin_hash TEXT NOT NULL UNIQUE,
    role TEXT NOT NULL CHECK (role IN ('cashier','stock_controller','manager','admin')),
    active INTEGER NOT NULL DEFAULT 1, must_change_pin INTEGER NOT NULL DEFAULT 0,
    email CITEXT, created_at TEXT NOT NULL DEFAULT (to_char(LOCALTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));

CREATE UNIQUE INDEX ux_staff_email ON staff(email) WHERE email IS NOT NULL;

CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);

CREATE TABLE sessions (
    token_hash TEXT PRIMARY KEY, staff_id INTEGER NOT NULL REFERENCES staff(id),
    created_at TEXT NOT NULL, last_seen TEXT NOT NULL, expires_at TEXT NOT NULL,
    ip TEXT, terminal_id TEXT);

CREATE INDEX ix_sessions_staff ON sessions(staff_id);

CREATE TABLE suppliers (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name CITEXT NOT NULL UNIQUE, phone TEXT, email TEXT,
    notes TEXT, active INTEGER NOT NULL DEFAULT 1);

CREATE TABLE ingredients (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name CITEXT NOT NULL UNIQUE,
    unit TEXT NOT NULL CHECK (unit IN ('g','ml','pcs')), cost_per_unit DOUBLE PRECISION NOT NULL DEFAULT 0,
    par_level DOUBLE PRECISION NOT NULL DEFAULT 0, count_daily INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, sku TEXT, barcode TEXT, category TEXT, critical_level DOUBLE PRECISION NOT NULL DEFAULT 0, supplier_id INTEGER REFERENCES suppliers(id));

CREATE UNIQUE INDEX ux_ing_sku ON ingredients(sku) WHERE sku IS NOT NULL;

CREATE UNIQUE INDEX ux_ing_barcode ON ingredients(barcode) WHERE barcode IS NOT NULL;

CREATE TABLE categories (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name CITEXT NOT NULL UNIQUE, sort INTEGER NOT NULL DEFAULT 0, major_group TEXT);

CREATE TABLE menu_items (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name CITEXT NOT NULL UNIQUE,
    category_id INTEGER REFERENCES categories(id), price DOUBLE PRECISION NOT NULL, active INTEGER NOT NULL DEFAULT 1, sku TEXT, barcode TEXT, description TEXT, variant_group TEXT, variant TEXT, available_days TEXT, sort INTEGER NOT NULL DEFAULT 0, flag TEXT);

CREATE UNIQUE INDEX ux_menu_sku ON menu_items(sku) WHERE sku IS NOT NULL;

CREATE UNIQUE INDEX ux_menu_barcode ON menu_items(barcode) WHERE barcode IS NOT NULL;

CREATE TABLE recipe_lines (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, menu_item_id INTEGER NOT NULL REFERENCES menu_items(id) ON DELETE CASCADE,
    ingredient_id INTEGER NOT NULL REFERENCES ingredients(id), qty DOUBLE PRECISION NOT NULL CHECK (qty > 0),
    UNIQUE (menu_item_id, ingredient_id));

CREATE TABLE import_batches (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, kind TEXT NOT NULL, filename TEXT, sha256 TEXT NOT NULL,
    staff_id INTEGER REFERENCES staff(id), created_at TEXT NOT NULL DEFAULT (to_char(LOCALTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    summary TEXT, UNIQUE (kind, sha256));

CREATE TABLE days (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, business_date TEXT NOT NULL UNIQUE,
    status TEXT NOT NULL CHECK (status IN ('open','closed')),
    opened_by INTEGER REFERENCES staff(id), opened_at TEXT,
    closed_by INTEGER REFERENCES staff(id), closed_at TEXT, notes TEXT, source TEXT NOT NULL DEFAULT 'app', covers_to TEXT, import_batch_id INTEGER REFERENCES import_batches(id));

CREATE UNIQUE INDEX ux_one_open_day ON days(status) WHERE status = 'open';

CREATE TABLE shifts (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, staff_id INTEGER NOT NULL REFERENCES staff(id), day_id INTEGER NOT NULL REFERENCES days(id),
    status TEXT NOT NULL CHECK (status IN ('open','closed')),
    opening_float DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK (opening_float >= 0),
    opened_at TEXT NOT NULL, closed_at TEXT, closed_by INTEGER REFERENCES staff(id),
    expected_cash DOUBLE PRECISION, counted_cash DOUBLE PRECISION, cash_variance DOUBLE PRECISION, notes TEXT);

CREATE UNIQUE INDEX ux_shift_open ON shifts(staff_id) WHERE status = 'open';

CREATE TABLE orders (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, day_id INTEGER NOT NULL REFERENCES days(id), number INTEGER NOT NULL,
    staff_id INTEGER NOT NULL REFERENCES staff(id),
    created_at TEXT NOT NULL DEFAULT (to_char(LOCALTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')), total DOUBLE PRECISION NOT NULL,
    payment_method TEXT NOT NULL CHECK (payment_method IN ('cash','mpesa','card')),
    amount_tendered DOUBLE PRECISION, payment_ref TEXT,
    status TEXT NOT NULL DEFAULT 'paid' CHECK (status IN ('paid','void')),
    void_reason TEXT, voided_by INTEGER REFERENCES staff(id), client_ref TEXT, request_hash TEXT, subtotal DOUBLE PRECISION, discount DOUBLE PRECISION NOT NULL DEFAULT 0, discount_reason TEXT, discount_by INTEGER REFERENCES staff(id), tax DOUBLE PRECISION NOT NULL DEFAULT 0, tax_rate DOUBLE PRECISION NOT NULL DEFAULT 0, tax_inclusive INTEGER NOT NULL DEFAULT 1, shift_id INTEGER REFERENCES shifts(id), payment_status TEXT NOT NULL DEFAULT 'manual_confirmed', refunded DOUBLE PRECISION NOT NULL DEFAULT 0, terminal_id TEXT, order_type TEXT NOT NULL DEFAULT 'Dine in', guests INTEGER CHECK (guests IS NULL OR guests BETWEEN 0 AND 500), tab_id INTEGER, server_id INTEGER REFERENCES staff(id), UNIQUE (day_id, number));

CREATE UNIQUE INDEX ux_orders_client_ref ON orders(client_ref) WHERE client_ref IS NOT NULL;

CREATE INDEX ix_orders_payref ON orders(payment_method, payment_ref);

CREATE INDEX ix_orders_day ON orders(day_id, status);

CREATE INDEX ix_orders_created ON orders(created_at);

CREATE TABLE order_items (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
    menu_item_id INTEGER NOT NULL REFERENCES menu_items(id), name TEXT NOT NULL,
    price DOUBLE PRECISION NOT NULL, qty INTEGER NOT NULL CHECK (qty > 0), note TEXT);

CREATE TABLE day_stock (
    day_id INTEGER NOT NULL REFERENCES days(id), ingredient_id INTEGER NOT NULL REFERENCES ingredients(id),
    opening DOUBLE PRECISION NOT NULL DEFAULT 0, delivered DOUBLE PRECISION, sold DOUBLE PRECISION, wasted DOUBLE PRECISION, expected DOUBLE PRECISION,
    counted DOUBLE PRECISION, variance DOUBLE PRECISION, reason TEXT, note TEXT, adjusted DOUBLE PRECISION, PRIMARY KEY (day_id, ingredient_id));

CREATE TABLE purchase_orders (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, supplier_id INTEGER NOT NULL REFERENCES suppliers(id),
    status TEXT NOT NULL CHECK (status IN ('draft','ordered','partial','received','cancelled')),
    expected_date TEXT, notes TEXT,
    created_by INTEGER REFERENCES staff(id), created_at TEXT NOT NULL DEFAULT (to_char(LOCALTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    ordered_at TEXT, closed_at TEXT);

CREATE TABLE po_lines (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, po_id INTEGER NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE,
    ingredient_id INTEGER NOT NULL REFERENCES ingredients(id),
    qty_ordered DOUBLE PRECISION NOT NULL CHECK (qty_ordered > 0),
    qty_received DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK (qty_received >= 0),
    unit_cost DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
    UNIQUE (po_id, ingredient_id));

CREATE TABLE refunds (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id),
    day_id INTEGER NOT NULL REFERENCES days(id), shift_id INTEGER REFERENCES shifts(id),
    amount DOUBLE PRECISION NOT NULL CHECK (amount >= 0), tax DOUBLE PRECISION NOT NULL DEFAULT 0,
    method TEXT NOT NULL CHECK (method IN ('cash','mpesa','card')), restocked INTEGER NOT NULL DEFAULT 0,
    reason TEXT NOT NULL, staff_id INTEGER NOT NULL REFERENCES staff(id), approved_by INTEGER REFERENCES staff(id),
    client_ref TEXT, created_at TEXT NOT NULL DEFAULT (to_char(LOCALTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));

CREATE UNIQUE INDEX ux_refund_ref ON refunds(client_ref) WHERE client_ref IS NOT NULL;

CREATE INDEX ix_refunds_day ON refunds(day_id);

CREATE TABLE refund_lines (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, refund_id INTEGER NOT NULL REFERENCES refunds(id) ON DELETE CASCADE,
    order_item_id INTEGER NOT NULL REFERENCES order_items(id), qty INTEGER NOT NULL CHECK (qty > 0),
    amount DOUBLE PRECISION NOT NULL);

CREATE TABLE stock_movements (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, day_id INTEGER NOT NULL REFERENCES days(id),
    ingredient_id INTEGER NOT NULL REFERENCES ingredients(id),
    type TEXT NOT NULL CHECK (type IN ('delivery','sale','void','refund','waste','adjustment','external_sale')),
    qty DOUBLE PRECISION NOT NULL, unit_cost DOUBLE PRECISION,
    order_id INTEGER REFERENCES orders(id), order_item_id INTEGER REFERENCES order_items(id),
    po_line_id INTEGER REFERENCES po_lines(id), refund_id INTEGER REFERENCES refunds(id),
    reason TEXT, note TEXT, staff_id INTEGER REFERENCES staff(id), client_ref TEXT,
    created_at TEXT NOT NULL DEFAULT (to_char(LOCALTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));

CREATE INDEX ix_mov_day ON stock_movements(day_id, ingredient_id);

CREATE INDEX ix_mov_order ON stock_movements(order_id);

CREATE INDEX ix_mov_ing ON stock_movements(ingredient_id, created_at);

CREATE UNIQUE INDEX ux_mov_client_ref ON stock_movements(client_ref) WHERE client_ref IS NOT NULL;

CREATE TABLE audit_log (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, at TEXT NOT NULL DEFAULT (to_char(LOCALTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    staff_id INTEGER REFERENCES staff(id), action TEXT NOT NULL, entity TEXT, entity_id INTEGER,
    details TEXT, ip TEXT);

CREATE INDEX ix_audit_at ON audit_log(at);

CREATE TABLE terminals (
    id TEXT PRIMARY KEY, label TEXT, first_seen TEXT NOT NULL, last_seen TEXT NOT NULL,
    user_agent TEXT, active INTEGER NOT NULL DEFAULT 1);

CREATE TABLE licence (
    id INTEGER PRIMARY KEY CHECK (id = 1), token TEXT NOT NULL, installed_at TEXT NOT NULL,
    installed_by INTEGER REFERENCES staff(id), last_valid_at TEXT);

CREATE TABLE licence_revocations (licence_id TEXT PRIMARY KEY, revoked_at TEXT NOT NULL, list_issued TEXT);

CREATE TABLE tabs (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, day_id INTEGER NOT NULL REFERENCES days(id), label CITEXT NOT NULL,
    order_type TEXT NOT NULL DEFAULT 'Dine in', guests INTEGER CHECK (guests IS NULL OR guests BETWEEN 0 AND 500),
    staff_id INTEGER NOT NULL REFERENCES staff(id),
    status TEXT NOT NULL CHECK (status IN ('open','paid','cancelled')),
    opened_at TEXT NOT NULL, closed_at TEXT, order_id INTEGER REFERENCES orders(id),
    cancel_reason TEXT, cancelled_by INTEGER REFERENCES staff(id), client_ref TEXT);

CREATE UNIQUE INDEX ux_tab_open_label ON tabs(label) WHERE status = 'open';

CREATE UNIQUE INDEX ux_tab_client_ref ON tabs(client_ref) WHERE client_ref IS NOT NULL;

CREATE TABLE tab_lines (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tab_id INTEGER NOT NULL REFERENCES tabs(id) ON DELETE CASCADE,
    menu_item_id INTEGER NOT NULL REFERENCES menu_items(id), qty INTEGER NOT NULL CHECK (qty > 0), note TEXT,
    added_by INTEGER NOT NULL REFERENCES staff(id), added_at TEXT NOT NULL, batch_ref TEXT, sent_at TEXT,
    removed_at TEXT, removed_by INTEGER REFERENCES staff(id), removed_reason TEXT, approved_by INTEGER REFERENCES staff(id));

CREATE INDEX ix_tab_lines_tab ON tab_lines(tab_id);

CREATE INDEX ix_tab_lines_batch ON tab_lines(batch_ref);
